import {translate as t,locale} from './i18n.js';
import {validateDocument,locales} from './site-schema.js';
const $=id=>document.getElementById(id),state={key:'site',value:null,original:null,sha:null,csrf:null,dirty:false,busy:false,canPublish:false,editLocale:locale,json:false};
const fieldNames={schemaVersion:'Schema version',displayName:'Display name',appearance:'Appearance',accent:'Accent color',highlight:'Highlight color',radius:'Corner radius',motion:'Enable motion',home:'Home',eyebrow:'Eyebrow',title:'Title',description:'Description',about:'About',intro:'Introduction',sections:'Sections',text:'Text',contacts:'Contacts',id:'Item ID',url:'URL',label:'Label',note:'Hover note',friends:'Companions',name:'Name',linksUrl:'Companion page URL',body:'Article body',path:'Page path',category:'Category',city:'City',address:'Address',lng:'Longitude',lat:'Latitude',generatedAt:'Updated timestamp',spots:'Original venues',price:'Price',rating:'Rating',avatar:'Avatar image',articleUrl:'Article URL',amapUrl:'Amap URL'};
fieldNames.links='Recommended links';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function node(tag,text,className){const element=document.createElement(tag);if(text!==undefined)element.textContent=text;if(className)element.className=className;return element;}
function status(message,error=false){$('studio-status').textContent=message;$('studio-status').classList.toggle('is-error',error);}
function busy(value){state.busy=value;$('studio-editor').setAttribute('aria-busy',String(value));document.querySelectorAll('.rich-body').forEach(body=>{body.contentEditable=String(!value);});$('studio-fields').disabled=value;for(const id of ['studio-save','studio-reload','studio-logout','studio-document','studio-locale','studio-import','studio-json','visual-tab','json-tab','studio-preview-page','studio-export','studio-check','studio-restore'])$(id).disabled=value||(id==='studio-save'&&!state.canPublish);}
const repositoryMessages={"github-token-invalid":"GitHub rejected the configured token. Update the production WEBSITE_GITHUB_TOKEN secret.","github-permission":"GitHub denied repository access. Check the selected repository and Contents permission.","github-rate-limit":"GitHub rate limit reached. Wait before reloading; no write was attempted.","github-network":"Could not reach GitHub. Reload the document; no write was attempted.","github-response-invalid":"GitHub returned an unexpected document response. No write was attempted.","github-document-invalid":"The repository document failed validation. Review its source JSON before publishing.","github-unavailable":"GitHub could not serve this document. Reload later; no write was attempted.","github-publish-rejected":"GitHub rejected publication. Check Contents read/write access; no confirmed save was returned."};
function repositoryMessage(code,http){return t(repositoryMessages[code]||'Could not complete this request.')+(Number.isInteger(http)?' (GitHub HTTP '+http+')':'');}
function friendly(error){if(Object.hasOwn(repositoryMessages,error.code||''))return repositoryMessage(error.code,error.upstreamStatus);const messages={401:'Authentication failed or the session expired. Your draft is still here.',403:'The request was refused. Reload the studio and sign in again.',409:'This document changed elsewhere. Export your draft before reloading.',429:'Too many attempts. Please wait one minute.',503:'Studio setup is incomplete. Check the runtime secrets in Cloudflare.',502:'The remote service did not confirm the operation. Check GitHub before retrying.'};return t(messages[error.status]||'Could not complete this request.')+(error.message?'\n'+error.message:'');}
async function api(path,options={}){const response=await fetch('/api/studio/'+path,{...options,credentials:'same-origin',cache:'no-store',headers:{...(options.method?{'Content-Type':'application/json','X-Studio-CSRF':state.csrf||''}:{}),...options.headers},signal:AbortSignal.timeout(35000)});let data;try{data=await response.json();}catch{throw Object.assign(new Error('Unexpected server response'),{status:response.status});}if(!response.ok)throw Object.assign(new Error(data.error||'Request failed'),{status:response.status,code:data.code,operation:data.operation,upstreamStatus:data.upstreamStatus});return data;}
function at(path){return path.reduce((value,key)=>value[key],state.value);}
function set(path,value){const parent=at(path.slice(0,-1));parent[path.at(-1)]=value;state.dirty=true;$('studio-dirty').textContent=t('Unsaved draft');requestAnimationFrame(preview);}
function changed(){state.dirty=true;$('studio-dirty').textContent=t('Unsaved draft');requestAnimationFrame(preview);}
function readJson(){if(state.json){const value=JSON.parse($('studio-json').value);validateDocument(state.key,value,state.original);state.value=value;}validateDocument(state.key,state.value,state.original);return state.value;}
function arrayTemplate(path){const key=path.at(-1);if(key==='spots')return {name:'',city:'',address:'',lng:0,lat:0,category:'Food',articleUrl:'',amapUrl:'',price:null,rating:null};if(key==='sections')return {title:'',text:''};const languages=()=>Object.fromEntries(locales.map(code=>[code,'']));if(key==='contacts')return {id:'contact-'+Date.now().toString(36),url:'',label:languages(),note:languages()};if(key==='links')return {id:'resource-'+Date.now().toString(36),name:'',url:'',category:'Reference / tools',description:languages()};if(key==='friends')return {id:'friend-'+Date.now().toString(36),name:'',url:'',linksUrl:'',description:languages()};return '' ;}
function field(value,path,label){
 if(Array.isArray(value)){const group=node('details',undefined,'schema-group');group.open=path.length<2;group.append(node('summary',label+' · '+value.length));value.forEach((item,index)=>{const wrap=node('div',undefined,'schema-array-item');wrap.append(field(item,[...path,index],String(index+1)));if(!state.key.startsWith('pages-')){const remove=node('button',t('Remove item'));remove.type='button';remove.addEventListener('click',()=>{value.splice(index,1);changed();renderFields();});wrap.append(remove);}group.append(wrap);});if(!state.key.startsWith('pages-')){const add=node('button',t('Add item'),'array-add');add.type='button';add.addEventListener('click',()=>{value.push(arrayTemplate(path));changed();renderFields();});group.append(add);}return group;}
 if(value&&typeof value==='object'){const group=node('details',undefined,'schema-group');group.open=path.length<2;group.append(node('summary',label));let entries=Object.entries(value);if(locales.every(code=>Object.hasOwn(value,code)))entries=entries.filter(([key])=>key===state.editLocale);if(state.key==='food'&&path.length===0)entries=entries.filter(([key])=>['generatedAt','spots'].includes(key));for(const [key,item] of entries)group.append(field(item,[...path,key],locales.includes(key)?key.toUpperCase():t(fieldNames[key]||key)));return group;}
 const wrap=node('label',undefined,'schema-field');wrap.append(node('span',label));const last=path.at(-1);
 if(last==='body'&&state.key.startsWith('pages-')){const container=node('div');const toolbar=node('div',undefined,'rich-toolbar');const body=node('div',undefined,'rich-body');body.contentEditable='true';body.setAttribute('role','textbox');body.setAttribute('aria-label',label);body.setAttribute('aria-multiline','true');body.innerHTML=value;for(const [caption,command,argument] of [['B','bold'],['I','italic'],['H2','formatBlock','h2'],['¶','formatBlock','p'],['•','insertUnorderedList']]){const button=node('button',caption);button.type='button';button.addEventListener('mousedown',event=>event.preventDefault());button.addEventListener('click',()=>{body.focus();document.execCommand(command,false,argument);set(path,body.innerHTML);});toolbar.append(button);}body.addEventListener('input',()=>set(path,body.innerHTML));body.addEventListener('paste',event=>{event.preventDefault();document.execCommand('insertText',false,event.clipboardData.getData('text/plain'));set(path,body.innerHTML);});container.append(toolbar,body);wrap.append(container);return wrap;}
 const numeric=typeof value==='number'||(value===null&&['price','rating'].includes(last));const input=node(typeof value==='string'&&(value.length>90||['text','description','intro','title','note'].includes(last))?'textarea':'input');if(input.tagName==='TEXTAREA')input.rows=value.length>250?5:3;else input.type=typeof value==='boolean'?'checkbox':numeric?'number':['accent','highlight'].includes(last)?'color':'text';if(numeric)input.step='any';if(typeof value==='boolean')input.checked=value;else input.value=value??'';if(['path','schemaVersion','coordinateSystem'].includes(last))input.readOnly=true;input.addEventListener('input',()=>set(path,typeof value==='boolean'?input.checked:numeric?(input.value===''?null:Number(input.value)):input.value));wrap.append(input);return wrap;
}
function renderFields(){const host=$('studio-fields');host.replaceChildren();host.append(field(state.value,[],t('Editable fields')));$('studio-json').value=JSON.stringify(state.value,null,2);}
function preview(){
 if(!state.value)return;let value=state.value;if(state.json)try{value=JSON.parse($('studio-json').value);}catch{return;}
 const dark=document.body.classList.contains('dark');const code=state.editLocale;let markup='',accent='#587e92',radius=16;
 try{validateDocument(state.key,value,state.original);
  if(state.key==='site'){accent=value.appearance.accent;radius=value.appearance.radius;const section=$('studio-preview-page').value;if(section==='home'){const home=value.home[code];markup=`<p class="eyebrow">${esc(home.eyebrow)}</p><h1>${esc(home.title).replace(/\n/g,'<br>')}</h1><p class="lead">${esc(home.description).replace(/\n/g,'<br>')}</p><img class="landscape" src="/assets/moon-landscape.svg" alt="">`;}else if(section==='about'){const about=value.about[code];markup=`<img class="portrait" src="/assets/avatar-portrait.jpg" alt=""><h1>${esc(about.title)}</h1><p class="lead">${esc(about.intro)}</p>`+about.sections.map(s=>`<section><h2>${esc(s.title)}</h2><p>${esc(s.text).replace(/\n/g,'<br>')}</p></section>`).join('');}else markup=`<h1>${esc(t('My companions ↗'))}</h1>`+value.friends.map(friend=>`<section><h2>${esc(friend.name)}</h2><p>${esc(friend.description[code])}</p><small>${esc(friend.url)}</small></section>`).join('');markup+=`<section class="contacts">${value.contacts.map(contact=>`<span title="${esc(contact.note[code])}">${esc(contact.label[code])}</span>`).join('')}</section>`;}
  else if(state.key.startsWith('pages-')){const index=Math.min(Number($('studio-preview-page').value)||0,value.length-1);const page=value[index];markup=`<small>${esc(page.label)}</small><h1>${esc(page.title)}</h1>${page.body}`;}
  else if(state.key==='resources')markup=`<h1>${esc(t('Recommended links'))}</h1>`+value.links.map(item=>`<section><h2>${esc(item.name)}</h2><p>${esc(item.description[code])}</p><small>${esc(item.url)}</small></section>`).join('');
  else if(state.key==='food')markup=`<h1>${esc(t('My original food collection'))}</h1>`+value.spots.map(spot=>`<section><h2>${esc(spot.name||t('New item'))}</h2><p>${esc(spot.city)} · ${esc(spot.address)}</p><small>${esc(spot.lng)}, ${esc(spot.lat)} · GCJ-02</small></section>`).join('');
  else markup=`<h1>${esc(t('Interface translations'))}</h1>`+Object.entries(value[code]).slice(0,40).map(([key,text])=>`<section><small>${esc(key)}</small><p>${esc(text)}</p></section>`).join('');
 }catch(error){markup=`<h2>${esc(t('Review the draft fields before publishing.'))}</h2><p>${esc(error.message)}</p>`;}
 $('studio-preview').srcdoc=`<!doctype html><html lang="${code}"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{margin:0;padding:35px;color-scheme:${dark?'dark':'light'};background:${dark?'#17262e':'#f5f6f2'};color:${dark?'#e1e9e8':'#263b4a'};font:14px/1.9 'Segoe UI',sans-serif}h1{font:42px/1.25 Georgia,serif;letter-spacing:-1px;color:${accent}}h2{font:25px/1.4 Georgia,serif;margin:0 0 12px}p{color:${dark?'#acbdc4':'#647981'}}section{padding:22px 0;border-top:1px solid #dfe5e2}a{color:${accent}}.eyebrow,small{font-size:10px;letter-spacing:1px}.lead{font-size:17px}.landscape{width:100%;max-height:240px;object-fit:contain}.portrait{width:100px;float:right;border-radius:${radius}px;margin:0 0 20px 20px}.contacts{display:flex;gap:15px;flex-wrap:wrap;font-size:11px}.contacts span{padding:8px 12px;background:#e8efed;border-radius:${radius}px}</style><body>${markup}</body></html>`;
}
function previewOptions(){const select=$('studio-preview-page');select.replaceChildren();const items=state.key.startsWith('pages-')?state.value.map((p,i)=>[String(i),p.title]):[['home',t('Home')],['about',t('About')],['links',t('Companions')]];for(const [value,label] of items){const option=node('option',label);option.value=value;select.append(option);}select.hidden=!['site','pages-en','pages-zh','pages-ru','pages-ja'].includes(state.key);}
async function loadDocument(key){if(state.dirty&&!confirm(t('Discard unsaved changes? Export first if you need a copy.'))){$('studio-document').value=state.key;return;}$('studio-document').value=key;busy(true);status(t('Reading the current repository document…'));try{const data=await api('document?key='+encodeURIComponent(key));state.key=key;state.value=data.value;state.original=structuredClone(data.value);state.sha=data.sha;if(data.access)state.canPublish=data.access.canPublish===true;state.dirty=false;state.json=false;$('studio-fields').hidden=false;$('studio-json-label').hidden=true;$('visual-tab').setAttribute('aria-pressed','true');$('json-tab').setAttribute('aria-pressed','false');$('studio-dirty').textContent=t('No unsaved changes');renderFields();previewOptions();preview();status(data.access?.warningCode?t('Loaded current public repository content. Publishing is disabled until authenticated access is restored.')+'\n'+repositoryMessage(data.access.warningCode,data.access.upstreamStatus):state.canPublish?t('Ready to edit. Nothing is published until you save.'):t('Publishing is not configured. You can preview and export a draft.'),!!data.access?.warningCode);}catch(error){status(friendly(error),true);$('studio-document').value=state.key;}finally{busy(false);}}
async function enter(data){window.dispatchEvent?.(new Event('studio-unlocked'));state.csrf=data.csrf;state.canPublish=data.canPublish;$('studio-login').hidden=true;$('studio-editor').hidden=false;await loadDocument(state.key);}
$('login-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{const password=$('studio-password').value;const data=await api('login',{method:'POST',body:JSON.stringify({password})});await enter(data);}catch(error){status(friendly(error),true);}finally{$('studio-password').value='';button.disabled=false;}});
const utility=node('div',undefined,'studio-utility');
for(const [id,label] of [['studio-check','Check draft'],['studio-restore','Restore loaded version']]){const button=node('button',t(label));button.id=id;button.type='button';button.disabled=true;utility.append(button);}
utility.append(node('span',t('Preview follows site theme.'),'studio-small'));
$('studio-fields').before(utility);
$('studio-check').addEventListener('click',()=>{if(state.busy||!state.value)return;try{readJson();preview();status(t('Draft is valid. Nothing has been published.'));}catch(error){status(t('Review the draft fields before publishing.')+'\n'+t(error.message),true);}});
$('studio-restore').addEventListener('click',()=>{if(state.busy||!state.original)return;if(state.dirty&&!confirm(t('Discard unsaved changes? Export first if you need a copy.')))return;state.value=structuredClone(state.original);state.dirty=false;renderFields();previewOptions();preview();$('studio-dirty').textContent=t('No unsaved changes');status(t('Loaded version restored. Nothing has been published.'));});
new MutationObserver(()=>{if(state.value)requestAnimationFrame(preview);}).observe(document.body,{attributes:true,attributeFilter:['class']});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'&&!$('studio-editor').hidden){event.preventDefault();if(!state.busy&&state.canPublish&&!$('studio-save').disabled)$('studio-save').click();}});
$('studio-document').addEventListener('change',()=>loadDocument($('studio-document').value));$('studio-locale').value=state.editLocale;$('studio-locale').addEventListener('change',()=>{try{readJson();state.editLocale=$('studio-locale').value;renderFields();preview();}catch(error){$('studio-locale').value=state.editLocale;status(t('Review the draft fields before publishing.')+'\n'+t(error.message),true);}});$('studio-preview-page').addEventListener('change',preview);$('studio-reload').addEventListener('click',()=>loadDocument(state.key));
for(const [id,json] of [['visual-tab',false],['json-tab',true]])$(id).addEventListener('click',()=>{try{readJson();state.json=json;$('studio-fields').hidden=json;$('studio-json-label').hidden=!json;$('studio-json').value=JSON.stringify(state.value,null,2);$('visual-tab').setAttribute('aria-pressed',String(!json));$('json-tab').setAttribute('aria-pressed',String(json));if(!json)renderFields();preview();}catch(error){status(t('Review the draft fields before publishing.')+'\n'+t(error.message),true);}});
$('studio-json').addEventListener('input',changed);
$('studio-save').addEventListener('click',async()=>{let value;try{value=structuredClone(readJson());}catch(error){status(t('Review the draft fields before publishing.')+'\n'+error.message,true);return;}if(!confirm(t('Publish these changes publicly to GitHub?')))return;busy(true);status(t('Saving to GitHub. Do not close this page…'));try{const receipt=await api('document?key='+encodeURIComponent(state.key),{method:'PUT',body:JSON.stringify({sha:state.sha,value})});if(!receipt.saved||!receipt.commit)throw new Error('No publication receipt');state.sha=receipt.sha;state.original=structuredClone(value);state.dirty=false;$('studio-dirty').textContent=t('No unsaved changes');status(t('Saved to GitHub. Deployment is a separate step; check the repository build.')+'\n'+receipt.url);}catch(error){status(friendly(error),true);}finally{busy(false);}});
$('studio-export').addEventListener('click',()=>{try{const value=readJson(),url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)+'\n'],{type:'application/json'}));const anchor=node('a');anchor.href=url;anchor.download='frostmoon-'+state.key+'-draft.json';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){status(t('Review the draft fields before publishing.')+'\n'+t(error.message),true);}});
$('studio-import').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>300000)throw new Error('Draft is too large');const value=JSON.parse(await file.text());validateDocument(state.key,value,state.original);state.value=value;changed();renderFields();previewOptions();preview();}catch(error){status(t('Could not import this draft.')+'\n'+error.message,true);}finally{event.target.value='';}});
$('studio-logout').addEventListener('click',async()=>{if(state.dirty&&!confirm(t('Discard unsaved changes? Export first if you need a copy.')))return;try{await api('logout',{method:'POST',body:'{}'});state.value=null;state.original=null;state.csrf=null;state.dirty=false;window.dispatchEvent?.(new Event('studio-locked'));$('studio-fields').replaceChildren();$('studio-json').value='';$('studio-preview').srcdoc='';$('studio-editor').hidden=true;$('studio-login').hidden=false;status(t('Studio locked.'));}catch(error){status(friendly(error),true);}});
window.addEventListener('beforeunload',event=>{if(state.dirty){event.preventDefault();event.returnValue='';}});
try{const data=await api('session');if(data.authenticated)await enter(data);else status(t(data.configured?'Enter your owner password to continue.':'Studio setup is incomplete. Check the runtime secrets in Cloudflare.'),!data.configured);}catch(error){status(t('The studio backend is unavailable in this preview. Use the deployed HTTPS site.'),true);}
